#
# file_update.sh — 把一个文件上传为 AUTO-MAS 数据中心一个或多个文件的新版本（tus 断点续传）。
#
# 一个文件即完整客户端：内嵌上传程序与依赖锁定清单，运行时自动在临时目录建隔离 Python 环境、
# 按哈希安装依赖（只装 wheel，不执行任何安装脚本），上传完成后清理。调用方只需校验本文件的
# SHA-256 并传参执行，不需要自己处理 pip、venv 等细节。
#
# 用法：
#   AUTOMAS_TOKEN=ak_xxx.sk_xxx bash file_update.sh <文件> --file-id <ID> [--file-id <ID> ...] \
#       [--change-note <说明>] [--endpoint <URL>] [--chunk-mb <MB>] [--retries <N>]
#
# 需要：bash、python3（≥3.9，含 venv 模块）、base64。成功退出码 0，任何失败非 0。
#
# 此文件由 scripts/build_file_update.py 生成，请勿手改；修改 file_update.py 或
# file_update.requirements.txt 后重新生成。

set -euo pipefail

if [[ -z "${AUTOMAS_TOKEN:-}" ]]; then
  echo "file_update: AUTOMAS_TOKEN is not set" >&2
  exit 2
fi

PYTHON="${FILE_UPDATE_PYTHON:-}"
if [[ -z "$PYTHON" ]]; then
  for candidate in python3 python; do
    if command -v "$candidate" >/dev/null 2>&1 && "$candidate" -c 'import sys; sys.exit(sys.version_info < (3, 9))' 2>/dev/null; then
      PYTHON="$candidate"
      break
    fi
  done
fi
if [[ -z "$PYTHON" ]]; then
  echo "file_update: python3 (>= 3.9) is required" >&2
  exit 2
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/file_update.XXXXXXXX")"
cleanup() { rm -rf "$WORK"; }
trap cleanup EXIT

# 释放内嵌文件。base64 解码在 Linux（GNU）与 macOS（BSD）上参数不同，统一用 Python 解码，避免差异。
"$PYTHON" - "$WORK" <<'__FILE_UPDATE_UNPACK__'
import base64, pathlib, sys
work = pathlib.Path(sys.argv[1])
payloads = {
    "file_update.py": "",
    "requirements.txt": "",
}
for name, data in payloads.items():
    (work / name).write_bytes(base64.b64decode(data))
__FILE_UPDATE_UNPACK__

"$PYTHON" -m venv "$WORK/venv" >/dev/null
VENV_PY="$WORK/venv/bin/python"
[[ -x "$VENV_PY" ]] || VENV_PY="$WORK/venv/Scripts/python.exe"   # Windows（Git Bash）

# 依赖整树固定版本与哈希、只装 wheel：任何一个包被替换都会安装失败，也不会执行安装脚本。
# 安装时不把令牌传给 pip（只在最后运行上传程序时才传入）。
env -u AUTOMAS_TOKEN "$VENV_PY" -m pip install --quiet --disable-pip-version-check --no-input \
  --require-hashes --only-binary :all: -r "$WORK/requirements.txt"

# 不用 exec：保留 trap，结束后清理临时目录。退出码即上传程序的退出码。
"$VENV_PY" "$WORK/file_update.py" "$@"
